#!/usr/bin/env bash
# Renders a compact app "party" for this bar's active workspace only.
set -euo pipefail

readonly HYPR_SOCKET="$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/.socket2.sock"
readonly OUTPUT_NAME="${WAYBAR_OUTPUT_NAME:?Waybar did not provide an output name}"

app_icon() {
  case "${1,,}" in
    *ghostty*|*terminal*|foot|kitty|alacritty|wezterm) printf '' ;;
    zen|*firefox*|*chrom*|*brave*|*vivaldi*)             printf '' ;;
    code|*codium*|*cursor*)                               printf '󰨞' ;;
    discord|vesktop|webcord)                              printf '' ;;
    spotify)                                              printf '' ;;
    steam)                                                printf '' ;;
    nautilus|thunar|dolphin|yazi)                         printf '' ;;
    *)                                                    printf '󰣆' ;;
  esac
}

emit() {
  local workspace classes app text=""

  workspace=$(hyprctl -j monitors | jq -er --arg output "$OUTPUT_NAME" \
    '.[] | select(.name == $output) | .activeWorkspace.id') || {
    jq -nc '{text: ""}'
    return
  }

  classes=$(hyprctl -j clients | jq -r --argjson workspace "$workspace" \
    '.[] | select(.workspace.id == $workspace) | .class')

  while IFS= read -r app; do
    [[ -n "$app" ]] || continue
    text+=$(app_icon "$app")
  done <<< "$classes"

  jq -nc --arg text "$text" '{text: $text}'
}

emit

socat -U - "UNIX-CONNECT:$HYPR_SOCKET" |
while IFS= read -r event; do
  case "$event" in
    workspace*|focusedmon*|movewindow*|openwindow*|closewindow*|activewindow*)
      emit
      ;;
  esac
done

