#!/usr/bin/env bash
# Renders Papirus app icons for this bar's active workspace only.
set -euo pipefail

readonly HYPR_SOCKET="$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/.socket2.sock"
readonly OUTPUT_NAME="${WAYBAR_OUTPUT_NAME:?Waybar did not provide an output name}"
readonly OUTPUT_CLASS="${OUTPUT_NAME,,}"
readonly PAPIRUS_DIR="/usr/share/icons/Papirus/24x24/apps"
readonly STATE_DIR="$HOME/.cache/waybar"
readonly CSS_PATH="$HOME/.config/waybar/workspace-apps-${OUTPUT_CLASS}.css"

render_slot=0

app_icon_path() {
  case "${1,,}" in
    *ghostty*|*terminal*|foot|kitty|alacritty|wezterm) printf '%s/utilities-terminal.svg\n' "$PAPIRUS_DIR" ;;
    zen|*firefox*|*chrom*|*brave*|*vivaldi*)             printf '%s/firefox.svg\n' "$PAPIRUS_DIR" ;;
    code|*codium*|*cursor*)                               printf '%s/visual-studio-code.svg\n' "$PAPIRUS_DIR" ;;
    discord|vesktop|webcord)                              printf '%s/discord.svg\n' "$PAPIRUS_DIR" ;;
    spotify)                                              printf '%s/spotify.svg\n' "$PAPIRUS_DIR" ;;
    steam)                                                printf '%s/steam.svg\n' "$PAPIRUS_DIR" ;;
    nautilus|thunar|dolphin|yazi)                         printf '%s/system-file-manager.svg\n' "$PAPIRUS_DIR" ;;
    *)                                                    printf '%s/application-default-icon.svg\n' "$PAPIRUS_DIR" ;;
  esac
}

write_css() {
  local width="$1" image="$2" css_tmp="${CSS_PATH}.tmp"

  cat > "$css_tmp" <<EOF
#custom-workspace-apps.workspace-apps-${OUTPUT_CLASS} {
    background-image: url("${image}");
    background-position: center;
    background-repeat: no-repeat;
    background-size: ${width}px 20px;
    color: transparent;
    font-size: 1px;
    letter-spacing: 0;
    min-width: ${width}px;
    min-height: 20px;
    margin: 0;
    padding: 0;
}
EOF
  mv "$css_tmp" "$CSS_PATH"
}

clear_css() {
  local css_tmp="${CSS_PATH}.tmp"

  cat > "$css_tmp" <<EOF
#custom-workspace-apps.workspace-apps-${OUTPUT_CLASS} {
    background-image: none;
    min-width: 0;
    min-height: 0;
    margin: 0;
    padding: 0;
}
EOF
  mv "$css_tmp" "$CSS_PATH"
}

emit() {
  local workspace app icon image width
  local -a icons=() convert_args=(convert)

  workspace=$(hyprctl -j monitors | jq -er --arg output "$OUTPUT_NAME" \
    '.[] | select(.name == $output) | .activeWorkspace.id') || {
    clear_css
    jq -nc --arg class "workspace-apps-${OUTPUT_CLASS}" '{text: "", class: $class}'
    return
  }

  while IFS= read -r app; do
    [[ -n "$app" ]] || continue
    icon=$(app_icon_path "$app")
    [[ -f "$icon" ]] || icon="$PAPIRUS_DIR/application-default-icon.svg"
    icons+=("$icon")
  done < <(hyprctl -j clients | jq -r --argjson workspace "$workspace" \
    '.[] | select(.workspace.id == $workspace) | .class')

  if ((${#icons[@]} == 0)); then
    clear_css
    jq -nc --arg class "workspace-apps-${OUTPUT_CLASS}" '{text: "", class: $class}'
    return
  fi

  render_slot=$((1 - render_slot))
  image="$STATE_DIR/workspace-apps-${OUTPUT_CLASS}-${render_slot}.png"
  for icon in "${icons[@]}"; do
    convert_args+=("(" "$icon" -background none -gravity center -extent 28x20 ")")
  done
  convert_args+=(+append "$image")
  "${convert_args[@]}"

  width=$((${#icons[@]} * 28))
  write_css "$width" "$image"
  jq -nc --arg class "workspace-apps-${OUTPUT_CLASS}" '{text: " ", class: $class}'
}

mkdir -p "$STATE_DIR"
emit

socat -U - "UNIX-CONNECT:$HYPR_SOCKET" |
while IFS= read -r event; do
  case "$event" in
    workspace*|focusedmon*|movewindow*|openwindow*|closewindow*|activewindow*)
      emit
      ;;
  esac
done

#custom-workspace-apps.workspace-apps-edp-1 {
    background-image: none;
    min-width: 0;
    min-height: 0;
    margin: 0;
    padding: 0;
}

#custom-workspace-apps.workspace-apps-hdmi-a-1 {
    background-image: url("/home/krubics/.cache/waybar/workspace-apps-hdmi-a-1-0.png");
    background-position: center;
    background-repeat: no-repeat;
    background-size: 84px 20px;
    color: transparent;
    font-size: 1px;
    letter-spacing: 0;
    min-width: 84px;
    min-height: 20px;
    margin: 0;
    padding: 0;
}
